# name: small_vs_large_region_gap
# description: Among targets outside the span by a linear gap of 5-40, yes-rate when the nearest example is <=20 minus when the nearest example is >=60; observed < null means people compress large numbers (log-like magnitude) so equal linear gaps matter more among small numbers, which the linear-distance model fails to produce.
def test_statistic(df):
    g = df.groupby(["number_set", "target"], sort=False)["rating"].mean().reset_index()
    small, large = [], []
    for s, t, r in zip(g["number_set"], g["target"].astype(int), g["rating"]):
        ex = [int(x) for x in str(s).split(",")]
        gap = max(min(ex) - t, t - max(ex), 0)
        if gap < 5 or gap > 40:
            continue
        x = min(ex, key=lambda e: abs(e - t))
        if x <= 20:
            small.append(r)
        elif x >= 60:
            large.append(r)
    if not small or not large:
        return 0.0
    return float(np.mean(small) - np.mean(large))

# name: exact_example_target_yes
# description: Yes-rate on trials whose target is one of the shown examples, minus yes-rate on targets within 1-3 of the nearest example; observed > null means people treat a repeated example as near-certainly produced far more than nearby numbers, and the model under-produces this boost.
def test_statistic(df):
    g = df.groupby(["number_set", "target"], sort=False)["rating"].mean().reset_index()
    hit, near = [], []
    for s, t, r in zip(g["number_set"], g["target"].astype(int), g["rating"]):
        ex = [int(x) for x in str(s).split(",")]
        d = min(abs(e - t) for e in ex)
        if d == 0:
            hit.append(r)
        elif d <= 3:
            near.append(r)
    if not hit or not near:
        return 0.0
    return float(np.mean(hit) - np.mean(near))

# name: first_vs_last_example_proximity
# description: In sets of >=2 examples, among non-example targets within 1-10 of their nearest example, yes-rate when that nearest example was shown first minus when it was shown last; observed > null means people weight the first example (primacy) more than the model's recency-weighted memory allows, observed < null means recency is stronger than modelled.
def test_statistic(df):
    g = df.groupby(["number_set", "target"], sort=False)["rating"].mean().reset_index()
    first, last = [], []
    for s, t, r in zip(g["number_set"], g["target"].astype(int), g["rating"]):
        ex = [int(x) for x in str(s).split(",")]
        if len(ex) < 2 or t in ex:
            continue
        d = [abs(e - t) for e in ex]
        i = int(np.argmin(d))
        if d[i] > 10:
            continue
        if i == 0:
            first.append(r)
        elif i == len(ex) - 1:
            last.append(r)
    if not first or not last:
        return 0.0
    return float(np.mean(first) - np.mean(last))

# name: math_category_match_contrast
# description: For sets of >=2 examples that all belong to a mathematical category the model does not represent (perfect squares, powers of two, cubes, primes), yes-rate on targets inside that category minus yes-rate on targets outside it; observed > null means people use these categories and the model under-produces category-based generalization.
def test_statistic(df):
    g = df.groupby(["number_set", "target"], sort=False)["rating"].mean().reset_index()
    sq = {i * i for i in range(1, 11)}
    p2 = {2 ** i for i in range(0, 7)}
    cu = {i ** 3 for i in range(1, 5)}
    pr = {n for n in range(2, 101) if all(n % d for d in range(2, int(n ** 0.5) + 1))}
    cats = [sq, p2, cu, pr]
    inn, out = [], []
    for s, t, r in zip(g["number_set"], g["target"].astype(int), g["rating"]):
        ex = [int(x) for x in str(s).split(",")]
        if len(ex) < 2:
            continue
        hit = [c for c in cats if all(x in c for x in ex)]
        if not hit:
            continue
        (inn if any(t in c for c in hit) else out).append(r)
    if not inn or not out:
        return 0.0
    return float(np.mean(inn) - np.mean(out))

# name: same_decade_near_contrast
# description: Among targets outside the example set lying within 1-10 of their nearest example, yes-rate when the target shares that example's tens decade minus when it does not; observed > null means people use decade membership (which the model, with only size and final digit, lacks) and the model under-produces this contrast.
def test_statistic(df):
    g = df.groupby(["number_set", "target"], sort=False)["rating"].mean().reset_index()
    same, diff = [], []
    for s, t, r in zip(g["number_set"], g["target"].astype(int), g["rating"]):
        ex = [int(x) for x in str(s).split(",")]
        if t in ex:
            continue
        x = min(ex, key=lambda e: abs(e - t))
        if abs(x - t) > 10:
            continue
        (same if min(x, 99) // 10 == min(t, 99) // 10 else diff).append(r)
    if not same or not diff:
        return 0.0
    return float(np.mean(same) - np.mean(diff))

# name: within_set_target_spread
# description: For sets asked with >=8 distinct targets, the mean over sets of the SD of per-target yes-rates across targets; observed > null means people discriminate between targets of the same set more sharply than the model (model too smooth), observed < null means the model is too sharp.
def test_statistic(df):
    g = df.groupby(["number_set", "target"], sort=False)["rating"].mean().reset_index()
    sd = g.groupby("number_set")["rating"].agg(["std", "size"])
    sd = sd[sd["size"] >= 8]
    if len(sd) == 0:
        return 0.0
    return float(sd["std"].mean())
